1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import { describe, expect, it } from "vitest";
3	import {
4	  addPlayer,
5	  advanceLedger,
6	  assertLedger,
7	  assignSources,
8	  cacheRubbings,
9	  cancelChannel,
10	  checkLedger,
11	  chooseTheft,
12	  createLedger,
13	  disconnectPlayer,
14	  eligibleTheftTypes,
15	  expireReservation,
16	  findDuel,
17	  findPlayer,
18	  findRubbing,
19	  hashState,
20	  heldTypes,
21	  holdsAllTypes,
22	  progressChannel,
23	  quitPlayer,
24	  reconnectPlayer,
25	  reportDuelResult,
26	  reserveDuel,
27	  startCacheClaim,
28	  startCollect,
29	  unlockSource,
30	  type LedgerState,
31	  type LedgerStep,
32	  type RubbingLocation,
33	  type SourceSite,
34	} from "./index.js";
35	
36	function sites(preset: RulesPresetId): SourceSite[] {
37	  const { islands, sourcesPerIsland } = rulesPresets[preset];
38	  return Array.from({ length: islands * sourcesPerIsland }, (_, index) => ({
39	    island: Math.floor(index / sourcesPerIsland),
40	    x: 1000 * index,
41	    y: 500,
42	  }));
43	}
44	
45	/** Freezes a state deeply, so any operation that writes into its input throws. */
46	function deepFreeze<T>(value: T): T {
47	  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
48	  for (const child of Object.values(value)) deepFreeze(child);
49	  return Object.freeze(value);
50	}
51	
52	/**
53	 * A ledger under test: every operation runs on a frozen state, the invariant is checked after it, and a rejected
54	 * request must hand back the very state it was given.
55	 */
56	class Run {
57	  state: LedgerState;
58	  now = 1;
59	
60	  constructor(preset: RulesPresetId, players: readonly string[], seed = 11) {
61	    let state = createLedger({ preset, seed, sites: sites(preset) });
62	    for (const source of state.sources) state = unlockSource(state, { sourceId: source.id, tick: 0 }).state;
63	    for (const playerId of players) state = addPlayer(state, { playerId, tick: 0 }).state;
64	    assertLedger(state);
65	    this.state = deepFreeze(state);
66	  }
67	
68	  do<Q, R extends { readonly ok: boolean }>(op: (state: LedgerState, request: Q) => LedgerStep<R>, request: Q): R {
69	    const before = this.state;
70	    const { state, result } = op(before, request);
71	    assertLedger(state);
72	    if (!result.ok) expect(state).toBe(before);
73	    this.state = deepFreeze(state);
74	    return result;
75	  }
76	
77	  where(rubbingId: string): RubbingLocation {
78	    return findRubbing(this.state, rubbingId)!.location;
79	  }
80	
81	  sourceOf(rubbingId: string): string {
82	    return this.state.sources.find((source) => source.rubbingId === rubbingId)!.id;
83	  }
84	
85	  gold(playerId: string): number {
86	    return findPlayer(this.state, playerId)!.gold;
87	  }
88	
89	  /** Holds interact for the full six seconds from the next tick. */
90	  hold(playerId: string, ticks = this.state.rules.collectTicks) {
91	    let last;
92	    for (let index = 0; index < ticks; index++) last = this.do(progressChannel, { playerId, tick: ++this.now });
93	    return last!;
94	  }
95	
96	  collect(playerId: string, rubbingId: string): void {
97	    expect(this.do(startCollect, { playerId, sourceId: this.sourceOf(rubbingId), tick: this.now }).status).toBe("started");
98	    expect(this.hold(playerId).status).toBe("collected");
99	    expect(this.where(rubbingId)).toEqual({ kind: "player", playerId });
100	  }
101	
102	  duel(duelId: string, a: string, b: string, winner: string | null) {
103	    expect(this.do(reserveDuel, { duelId, players: [a, b], tick: ++this.now }).ok).toBe(true);
104	    return this.do(
105	      reportDuelResult,
106	      winner === null ? { duelId, tick: ++this.now, outcome: "draw" } : { duelId, tick: ++this.now, outcome: "win", winner },
107	    );
108	  }
109	}
110	
111	const player = (playerId: string): RubbingLocation => ({ kind: "player", playerId });
112	
113	describe("ledger state and content", () => {
114	  it("seals the slice's 8 and the alpha's 12 rubbings, one per source, all locked at first", () => {
115	    for (const [preset, count] of [["slice", 8], ["alpha", 12]] as const) {
116	      const state = createLedger({ preset, seed: 3, sites: sites(preset) });
117	      assertLedger(state);
118	      expect(state.rubbings).toHaveLength(count);
119	      expect(state.sources.every((source) => !source.unlocked)).toBe(true);
120	      for (const rubbing of state.rubbings) {
121	        const source = state.sources.find((candidate) => candidate.rubbingId === rubbing.id)!;
122	        expect(rubbing.location).toEqual({ kind: "source", sourceId: source.id });
123	        expect(rubbing.type).toBe(source.type);
124	      }
125	    }
126	  });
127	
128	  it("deals the rubbings onto islands from the seed alone", () => {
129	    const deal = (seed: number) => assignSources("alpha", sites("alpha"), seed).assignment.sources.map((source) => source.rubbingId);
130	    expect(deal(5)).toEqual(deal(5));
131	    const deals = new Set([1, 2, 3, 4, 5, 6].map((seed) => deal(seed).join(",")));
132	    expect(deals.size).toBeGreaterThan(1);
133	    expect(() => assignSources("slice", sites("alpha"), 1)).toThrow(/invalid source sites/);
134	  });
135	
136	  it("finds every broken rule in a corrupted state", () => {
137	    const run = new Run("slice", ["a", "b"]);
138	    run.collect("a", "sun-1");
139	    const state = run.state;
140	    const duplicated = { ...state, rubbings: [...state.rubbings, state.rubbings[0]!] };
141	    expect(checkLedger(duplicated).join("\n")).toMatch(/present 2 times/);
142	    const lost = { ...state, rubbings: state.rubbings.slice(1) };
143	    expect(checkLedger(lost).join("\n")).toMatch(/present 0 times/);
144	    const twoSuns = {
145	      ...state,
146	      rubbings: state.rubbings.map((rubbing) => (rubbing.id === "sun-2" ? { ...rubbing, location: player("a") } : rubbing)),
147	    };
148	    expect(checkLedger(twoSuns).join("\n")).toMatch(/holds two sun/);
149	    const nowhere = {
150	      ...state,
151	      rubbings: state.rubbings.map((rubbing) => (rubbing.id === "moon-1" ? { ...rubbing, location: player("ghost") } : rubbing)),
152	    };
153	    expect(checkLedger(nowhere).join("\n")).toMatch(/unknown player ghost/);
154	    const minted = { ...state, players: state.players.map((entry) => ({ ...entry, gold: entry.gold + 1 })) };
155	    expect(checkLedger(minted).join("\n")).toMatch(/balances sum/);
156	    const emptyCache = { ...state, caches: [{ id: "cache-9", x: 0, y: 0, createdTick: 0 }] };
157	    expect(checkLedger(emptyCache).join("\n")).toMatch(/cache cache-9 is empty/);
158	  });
159	});
160	
161	describe("collection (§4)", () => {
162	  it("takes six uninterrupted seconds at an unlocked source", () => {
163	    const run = new Run("slice", ["a"]);
164	    const sourceId = run.sourceOf("moon-2");
165	    expect(run.do(startCollect, { playerId: "a", sourceId, tick: run.now }).status).toBe("started");
166	    expect(run.hold("a", 119).status).toBe("held");
167	    expect(run.where("moon-2").kind).toBe("source");
168	    const done = run.do(progressChannel, { playerId: "a", tick: ++run.now });
169	    expect(done).toMatchObject({ status: "collected", rubbingId: "moon-2", channel: null });
170	    expect(done.transfers).toEqual([
171	      { rubbingId: "moon-2", from: { kind: "source", sourceId }, to: player("a"), revisionBefore: 0, revisionAfter: 1 },
172	    ]);
173	    expect(run.do(progressChannel, { playerId: "a", tick: ++run.now }).rejection).toBe("no-channel");
174	  });
175	
176	  it("resets progress on an interruption and ends it on cancel", () => {
177	    const run = new Run("slice", ["a"]);
178	    const sourceId = run.sourceOf("sun-1");
179	    run.do(startCollect, { playerId: "a", sourceId, tick: run.now });
180	    run.hold("a", 100);
181	    run.now += 2;
182	    const reset = run.do(progressChannel, { playerId: "a", tick: run.now });
183	    expect(reset.status).toBe("reset");
184	    expect(reset.channel).toMatchObject({ heldTicks: 0, startTick: run.now });
185	    expect(run.hold("a", 119).status).toBe("held");
186	    expect(run.do(cancelChannel, { playerId: "a", tick: run.now }).status).toBe("cancelled");
187	    expect(run.do(progressChannel, { playerId: "a", tick: ++run.now }).rejection).toBe("no-channel");
188	    expect(run.where("sun-1").kind).toBe("source");
189	    expect(run.do(cancelChannel, { playerId: "a", tick: run.now }).rejection).toBe("no-channel");
190	  });
191	
192	  it("ignores duplicate starts and stale progress", () => {
193	    const run = new Run("slice", ["a"]);
194	    const sourceId = run.sourceOf("sun-1");
195	    run.do(startCollect, { playerId: "a", sourceId, tick: run.now });
196	    run.hold("a", 10);
197	    expect(run.do(startCollect, { playerId: "a", sourceId, tick: run.now }).rejection).toBe("duplicate");
198	    expect(run.do(progressChannel, { playerId: "a", tick: run.now }).rejection).toBe("duplicate");
199	    expect(run.do(progressChannel, { playerId: "a", tick: run.now - 3 }).rejection).toBe("stale-tick");
200	    expect(findPlayer(run.state, "a")!.channel!.heldTicks).toBe(10);
201	  });
202	
203	  it("refuses a locked source, an emptied one, and a type the player holds, which stays sealed", () => {
204	    const run = new Run("slice", ["a", "b"]);
205	    const locked = createLedger({ preset: "slice", seed: 11, sites: sites("slice") });
206	    const withPlayer = addPlayer(locked, { playerId: "a", tick: 0 }).state;
207	    expect(startCollect(withPlayer, { playerId: "a", sourceId: locked.sources[0]!.id, tick: 0 }).result.rejection).toBe("source-locked");
208	
209	    run.collect("a", "sun-1");
210	    const refused = run.do(startCollect, { playerId: "a", sourceId: run.sourceOf("sun-2"), tick: run.now });
