import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
import { describe, expect, it } from "vitest";
import {
  addPlayer,
  advanceLedger,
  assertLedger,
  assignSources,
  cacheRubbings,
  cancelChannel,
  checkLedger,
