  disconnectPlayer,
  eligibleTheftTypes,
  expireReservation,
  findDuel,
  findPlayer,
  findRubbing,
  hashState,
  heldTypes,
  holdsAllTypes,
  progressChannel,
  quitPlayer,
  reconnectPlayer,
  reportDuelResult,
  reserveDuel,
