102	export interface ReportDuelResultRequest {
103	  readonly duelId: string;
104	  readonly tick: number;
105	  /** `cancelled`: both players forfeited on the same tick (§12), which settles like a draw. */
106	  readonly outcome: "win" | "draw" | "cancelled";
107	  /** The winner, for `win` only. */
108	  readonly winner?: string;
109	}
110	
111	/**
112	 * Records the fight's result once. A draw or cancellation settles at once with nothing moving. A win opens the
113	 * winner's theft choice window, or settles at once (gold only) when no type is eligible. Any later result message
114	 * for the duel, even a different one, changes nothing and returns the current result.
115	 */
116	export function reportDuelResult(state: LedgerState, request: ReportDuelResultRequest): LedgerStep<DuelResult> {
117	  const { duelId, tick, outcome, winner } = request;
118	  const bad = tickRejection(state, tick);
119	  if (bad) return rejected(state, bad, duelId);
120	  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
121	  if (!duel) return rejected(state, "unknown-duel", duelId);
122	  if (duel.phase !== "fighting") return rejected(state, "already-resolved", duelId);
123	  if (outcome === "win") {
124	    if (winner === undefined || !duel.players.includes(winner)) return rejected(state, "not-a-participant", duelId);
125	  } else if ((outcome !== "draw" && outcome !== "cancelled") || winner !== undefined) {
126	    return rejected(state, "invalid-request", duelId);
127	  }
128	  const effects = noEffects();
129	  const next = recordResult(atTick(state, tick), duel, outcome, winner ?? null, false, tick, effects);
130	  return applied(next, duelId, effects);
131	}
132	
133	/** Records a result for a duel still fighting; shared with a forfeit by a player who leaves. */
134	export function recordResult(
135	  state: LedgerState,
136	  duel: LedgerDuel,
137	  outcome: DuelResultRecord["outcome"],
138	  winner: string | null,
139	  forfeit: boolean,
140	  tick: number,
141	  effects: Effects,
142	): LedgerState {
143	  if (outcome !== "win") {
144	    const result: DuelResultRecord = { outcome, winner: null, loser: null, forfeit: false, tick };
145	    const settlement: DuelSettlement = {
146	      tick,
147	      stolenRubbingId: null,
148	      stolenType: null,
149	      choice: "none",
150	      gold: 0,
151	      goldSuppressed: false,
152	    };
153	    let next = replaceDuel(state, { ...duel, phase: "settled", result, settlement });
154	    for (const playerId of duel.players) {
155	      next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
156	    }
157	    return next;
158	  }
159	  const loser = duel.players[0] === winner ? duel.players[1] : duel.players[0];
160	  const decided: LedgerDuel = { ...duel, result: { outcome, winner, loser, forfeit, tick } };
161	  const next = replaceDuel(state, decided);
162	  if (eligibleTheftTypes(next, duel.id).length === 0) return commitWin(next, decided, tick, null, effects);
163	  return replaceDuel(next, { ...decided, phase: "choosing", choiceDeadline: tick + state.rules.theftChoiceTicks });
164	}
165	
166	/**
167	 * Commits a decided duel, once: validates eligibility again, moves the stolen rubbing (the winner's valid choice, or
168	 * the default), transfers gold unless suppressed, grants the loser a fresh rumor for the lost type, and returns every
169	 * other reserved rubbing to its owner (or to a cache where its owner left). A winner who has left takes nothing.
170	 */
171	export function commitWin(
172	  state: LedgerState,
173	  duel: LedgerDuel,
174	  tick: number,
175	  choice: RubbingType | null,
176	  effects: Effects,
177	): LedgerState {
178	  const result = duel.result;
179	  if (duel.phase === "settled" || result?.outcome !== "win" || result.winner === null || result.loser === null) {
180	    throw new Error(`duel ${duel.id} has no win to commit`);
181	  }
182	  const { winner, loser } = result;
183	  const winnerPlayer = findPlayer(state, winner);
184	  const loserPlayer = findPlayer(state, loser);
185	  if (!winnerPlayer || !loserPlayer) throw new Error(`duel ${duel.id} names an unknown player`);
186	  const winnerPresent = winnerPlayer.status !== "left";
187	
188	  const eligible = eligibleTheftTypes(state, duel.id);
189	  const chosen = choice !== null && eligible.includes(choice) ? choice : null;
190	  const stolenType = chosen ?? defaultTheftType(state, eligible);
191	  const stolen = stolenType === null ? undefined : reservedIn(state, duel.id, loser).find((rubbing) => rubbing.type === stolenType);
192	
193	  const previous = state.wins.find((win) => win.winner === winner && win.loser === loser);
194	  const goldSuppressed =
195	    winnerPresent && previous !== undefined && result.tick - previous.tick < state.rules.repeatWinWindowTicks;
196	  const gold = winnerPresent && !goldSuppressed ? pvpGoldTransfer(state.rules, loserPlayer.gold) : 0;
197	
198	  const settlement: DuelSettlement = {
199	    tick,
200	    stolenRubbingId: stolen?.id ?? null,
201	    stolenType: stolen ? stolen.type : null,
202	    choice: stolen === undefined ? "none" : chosen !== null ? "winner" : "default",
203	    gold,
204	    goldSuppressed,
205	  };
206	  let next = replaceDuel(state, { ...duel, phase: "settled", settlement });
207	  if (stolen) {
208	    next = moveRubbings(next, [{ rubbingId: stolen.id, to: { kind: "player", playerId: winner } }], effects);
209	    const lost = stolen.type;
210	    next = updatePlayer(next, loser, (player) => ({
211	      ...player,
212	      freshRumors: player.freshRumors.includes(lost) ? player.freshRumors : [...player.freshRumors, lost].sort(byTypeOrder),
213	    }));
214	  }
215	  if (gold > 0) {
216	    next = updatePlayer(next, loser, (player) => ({ ...player, gold: player.gold - gold }));
217	    next = updatePlayer(next, winner, (player) => ({ ...player, gold: player.gold + gold }));
218	  }
219	  if (winnerPresent) {
220	    const record = { winner, loser, tick: result.tick };
221	    next = {
222	      ...next,
223	      wins: previous ? next.wins.map((win) => (win === previous ? record : win)) : [...next.wins, record],
224	    };
225	  }
226	  for (const playerId of [winner, loser]) {
227	    next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
228	  }
229	  return next;
230	}
231	
232	export interface ChooseTheftRequest {
233	  /** The server-created duel result the choice refers to (§16). */
234	  readonly duelId: string;
235	  readonly playerId: string;
236	  readonly type: RubbingType;
237	  readonly tick: number;
238	}
239	
240	/** The winner's theft choice, before the deadline and for an eligible type; it commits the settlement at once. */
241	export function chooseTheft(state: LedgerState, request: ChooseTheftRequest): LedgerStep<DuelResult> {
242	  const { duelId, playerId, type, tick } = request;
243	  const bad = tickRejection(state, tick);
244	  if (bad) return rejected(state, bad, duelId);
245	  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
246	  if (!duel) return rejected(state, "unknown-duel", duelId);
247	  if (duel.phase === "settled") return rejected(state, "already-resolved", duelId);
248	  if (duel.phase !== "choosing" || duel.result === null || duel.choiceDeadline === null) {
249	    return rejected(state, "not-choosing", duelId);
250	  }
251	  if (playerId !== duel.result.winner) return rejected(state, "not-winner", duelId);
252	  if (tick >= duel.choiceDeadline) return rejected(state, "choice-window-closed", duelId);
253	  if (!rubbingTypeSchema.safeParse(type).success || !eligibleTheftTypes(state, duelId).includes(type)) {
254	    return rejected(state, "ineligible-type", duelId);
255	  }
256	  const effects = noEffects();
257	  const next = commitWin(atTick(state, tick), duel, tick, type, effects);
258	  return applied(next, duelId, effects);
259	}
260	
261	export interface AdvanceRequest {
262	  readonly tick: number;
263	}
264	
265	export interface AdvanceResult {
266	  readonly ok: boolean;
267	  readonly rejection: LedgerRejection | null;
268	  /** Duels whose choice window closed at this tick, settled with the default theft. */
269	  readonly settled: readonly LedgerDuel[];
270	  readonly transfers: readonly Transfer[];
271	  readonly cacheIds: readonly string[];
272	}
273	
274	/**
275	 * Moves the ledger's clock to `tick` and settles every duel whose choice window has closed with the default theft,
276	 * in reservation order. Call it once per world tick before that tick's requests.
277	 */
278	export function advanceLedger(state: LedgerState, request: AdvanceRequest): LedgerStep<AdvanceResult> {
279	  const bad = tickRejection(state, request.tick);
280	  if (bad) return { state, result: { ok: false, rejection: bad, settled: [], transfers: [], cacheIds: [] } };
281	  const { tick } = request;
282	  const effects = noEffects();
283	  let next = atTick(state, tick);
284	  const settled: string[] = [];
285	  for (const duel of state.duels) {
286	    if (duel.phase === "choosing" && duel.choiceDeadline !== null && tick >= duel.choiceDeadline) {
287	      next = commitWin(next, findDuel(next, duel.id)!, tick, null, effects);
288	      settled.push(duel.id);
289	    }
290	  }
291	  return {
292	    state: next,
293	    result: { ok: true, rejection: null, settled: settled.map((id) => findDuel(next, id)!), ...effects },
294	  };
295	}
